          );
          state.needs.happiness = Math.min(
            100,
            state.needs.happiness + (isBirthday ? 8 : 3),
          );
          // 检查好感阈值奖励
          if (typeof checkNpcAffinityRewards === "function") {
            checkNpcAffinityRewards(npc.id, state);
          }
          consumeAP(10);
        },
      });

      // NPC 委托任务（好感≥30且任务未完成）
      if (npc.favor) {
